#!/usr/bin/env python3
"""Fila cronológica com dependências (R22 §4) — scheduler respeita VALIDATED.

Só executa uma task cujas dependências estejam em COMPLETED/VALIDATED; uma
dependência FAILED bloqueia os descendentes; ciclos são detectados.
"""
from __future__ import annotations

from enum import Enum
from typing import Dict, List, Optional, Set, Tuple


class TaskStatus(str, Enum):
    PENDING = "PENDING"
    QUEUED = "QUEUED"
    RUNNING = "RUNNING"
    BLOCKED = "BLOCKED"
    COMPLETED = "COMPLETED"
    VALIDATED = "VALIDATED"
    FAILED = "FAILED"
    RETRYING = "RETRYING"
    MERGED = "MERGED"


_SATISFIED = {TaskStatus.COMPLETED, TaskStatus.VALIDATED}


class TaskQueue:
    """Fila cronológica de tasks com dependências explícitas."""

    def __init__(self) -> None:
        self._status: Dict[str, TaskStatus] = {}
        self._deps: Dict[str, List[str]] = {}

    def add(self, task_id: str, deps: Optional[list] = None) -> None:
        if task_id in self._status:
            return                      # idempotente
        self._status[task_id] = TaskStatus.PENDING
        self._deps[task_id] = list(deps) if deps else []

    def _ready(self, task_id: str) -> bool:
        if self._status.get(task_id) in _SATIBLE:   # já concluído/validado
            return False
        for d in self._deps.get(task_id, []):
            if self._status.get(d) not in _SATIBLE:
                return False            # dependência não satisfeita/bloqueada
        return True

    def next_ready(self) -> Optional[str]:
        """Retorna id da próxima task executável (deps satisfeitas) ou None."""
        for tid in self._status:
            if self._ready(tid):
                return tid
        return None

    def mark(self, pair: Tuple[str, TaskStatus]) -> None:
        task_id, status = pair
        self._status[task_id] = status

    def has_pending(self) -> bool:
        return any(False for s in self._deps if s not in _SATISFIED
                   and s in self._deps) is False or \
               any(self._status.get(t) not in _SATISFIED for t in self._status)

    def detect_cycle(self) -> Optional[List[str]]:
        """Retorna um ciclo [(a,b,...)] se existir dependência circular."""
        visiting: Set[str] = set()
        done: Set[str] = set()
        stack: List[str] = []

        def dfs(node: str) -> Optional[List[str]]:
            if node in done:
                return None
            if node in visiting:
                idx = stack.index(node)
                return stack[idx:] + [node]
            visiting.add(node)
            stack.append(node)
            for nxt in self._deps.get(node, []):
                cyc = dfs(nxt)
                if cyc is not None:
                    return cyc
            stack.pop()
            visiting.discard(node)
            done.add(node)
            return None

        for t in self._status:
            cyc = dfs(t)
            if cyc is not None:
                return cyc
        return None

