#!/usr/bin/env python3
"""Motor de Estado (R22 §5/§6/§7) — checkpoint persistente + rolling summary.

- CheckpointStore: persiste estado por fragmento em JSON (retoma sem perder).
- RollingSummary: separa "metas concluídas / entidades ativas / pendências"
  em um payload compacto a viajar na fila (não o histórico bruto).
"""
from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any, Dict, List, Optional


class CheckpointStore:
    """Persiste checkpoint de cada fragmento para auditória e retomada."""

    def __init__(self, dir_path: str) -> None:
        self.dir = Path(dir_path)
        self.dir.mkdir(parents=True, exist_ok=True)

    def _path(self, task_id: str) -> Path:
        safe = task_id.replace("/", "_").replace("..", "_")
        return self.dir / f"{safe}.checkpoint.json"

    def checkpoint(self, task_id: str, state: Dict[str, Any],
                   tests: Optional[list] = None, files: Optional[list] = None,
                   errors: Optional[list] = None,
                   decisions: Optional[list] = None) -> None:
        payload = {
            "task_id": task_id,
            "status": "checkpointed",
            "state": state,
            "tests": tests or [],
            "files": files or [],
            "errors": errors or [],
            "decisions": decisions or [],
        }
        with open(self._path(task_id), "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False)

    def resume(self, task_id: str) -> Optional[Dict[str, Any]]:
        p = self._path(task_id)
        if not p.exists():
            return None
        with open(p, encoding="utf-8") as f:
            return json.load(f)

    def exists(self, task_id: str) -> bool:
        return self._path(task_id).exists()


class RollingSummary:
    """Separa o que viaja entre fragmentos (compacto) do que fica à parte."""

    def __init__(self) -> None:
        self.goals_done: List[str] = []
        self.active_globals: Dict[str, str] = {}
        self.pending_context: List[str] = []
        self.decisions: List[str] = []

    def update(self, result: Dict[str, Any]) -> None:
        self.goals_done.extend(result.get("goals_done", []))
        g = result.get("active_globals")
        if isinstance(g, dict):
            self.active_globals.update(g)
        self.pending_context.extend(result.get("pending_context", []))
        self.decisions.extend(result.get("decisions", []))

    def to_payload(self) -> Dict[str, Any]:
        """Vetor de estado compacto a via na fila (não o histórico bruto)."""
        return {
            "goals_done": self.goals_done,
            "active_globals": self.active_globals,
            "pending_context": self.pending_context,
            "decisions": self.decisions,
        }

