        return self._path(task_id).exists()


class RollingSummary:
    """Separa o que viaja entre fragmentos (compacto) do que fica à parte."""

    def __init__(self) -> None:
        self.goals_done: List[str] = []
        self.active_globals: Dict[str, str] = {}
        self.pending_context: List[str] = []
        self.decisions: List[str] = []

    def update(self, result: Dict[str, Any]) -> None:
        self.goals_done.extend(result.get("goals_done", []))
        g = result.get("active_globals")
