            "active_globals": self.active_globals,
            "pending_context": self.pending_context,
            "decisions": self.decisions,
        }

    def merge_payloads(self, payloads: List[Dict[str, Any]]) -> "RollingSummary":
        out = RollingSummary()
        for p in payloads:
