#!/usr/bin/env python3
"""Orquestrador do Task Manager (R22 §13 pseudocódigo).

TASK → DECOMPOSE(se > janela) → QUEUE → EXECUTE → VALIDATE → CHECKPOINT
     → MERGE (semântico) → VALIDATE-MERGE → NEXT STAGE.

Nenhuma task é descartada por excesso de contexto: fragmenta até caber.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional

from task_manager.fragmenter import SemanticFragmenter, Fragment, rough_tokens
from task_manager.queue import TaskQueue, TaskStatus
from task_manager.state import CheckpointStore, RollingSummary
from task_manager.merger import TaskMerger, MergeConflict


@dataclass
class Task:
    id: str
    content: str
    meta: Dict = field(default_factory=dict)


@dataclass
class TaskResult:
    fragments: int
    final_content: str
    validated: bool
    conflicts: List[MergeConflict] = field(default_factory=list)


# Agente: callable que recebe 1 Fragment e devolve algo com `.content`
# (ou um dict com content/context_overflow) — execução pode ser LLM-free.
class _AgentOut:
    def __init__(self, content: str, context_overflow: bool = False) -> None:
        self.content = content
        self.context_overflow = context_overflow


class TaskManager:
    """Pipeline completo: fragmenta, enfileira, executa, valida, merge."""

    def __init__(self, agent: Callable[[Fragment], object], capacity: int,
                 store_dir: str, overlap_ratio: float = 0.15) -> None:
        self.agent = agent
        self.capacity = capacity
        self.store_dir = store_dir
        self.store = CheckpointStore(store_dir)
        self.merger = TaskMerger()
        self.fragmenter = SemanticFragmenter(max_tokens=capacity,
                                             overlap_ratio=overlap_ratio)

    def _run(self, frag: Fragment) -> object:
        return self.agent(frag)

    def _extract(self, out: object) -> str:
        # Se for um objeto com .content (dict ou _FragmentOut), usa; senão str.
        if isinstance(out, dict):
            return str(out.get("content", ""))
        return str(getattr(out, "content", out))

    def _overflow(self, out: object) -> bool:
        if isinstance(out, dict):
            return bool(out.get("context_overflow", False))
        return bool(getattr(out, "context_overflow", False))

    def execute_task(self, task: Task) -> TaskResult:
        if rough_tokens(task.content) <= self.capacity:
            # Task pequena: cabe → executa direto (1 fragmento).
            frag = Fragment(task_id=task.id, seq=1, total=1,
                            content=task.content, objective=task.id)
            out = self._run(frag)
            return TaskResult(fragments=1, final_content=self._extract(out),
                              validated=True)
        return self._fragmented(task)

    def _run_one(self, frag: Fragment, capacity: int) -> str:
        """Executa um fragmento, refragmentando se estourar (R22 §8.)."""
        f = frag
        for _ in range(3):                      # limita re-fragmentação
            out = self._run(f)
            if not self._overflow(out):
                return self._extract(out)
            # overflow → refragmenta a menor capacidade (metade)
            inner = SemanticFragmenter(max_tokens=max(1, capacity // 2),
                                       overlap_ratio=0.15)
            pieces = inner.chunk(f.content, f.task_id)
            if len(pieces) <= 1:
                return self._extract(out)      # não há como reduzir mais
            f = pieces[0]
        return self._extract(self._run(f))

    def _fragmented(self, task: Task) -> TaskResult:
        frags = self.fragmenter.chunk(task.content, task.id)
        queue = TaskQueue()
        for i, frag in enumerate(frags):
            queue.add(frag.task_id, deps=([frags[i-1].task_id] if i > 0 else []))

        results: List[str] = []
        summary = RollingSummary()
        while queue.has_pending():
            tid = queue.next_ready()
            if tid is None:
                break                       # bloqueado/dependência inválida
            frag = next((f for f in frags if f.task_id == tid), None)
            if frag is None:
                queue.mark((tid, TaskStatus.FAILED)); continue
            queue.mark((tid, TaskStatus.RUNNING))
            content = self._run_one(frag, self.capacity)
            # checkpoint (R22 §7)
            self.store.checkpoint(tid, {"partial": content[-400:]},
                                  files=[getattr(frag, "output_artifact", "")])
            queue.mark((tid, TaskStatus.COMPLETED))
            results.append(content)
            # vetor de estado compacto
            summary.update({"goals_done": [tid],
                            "active_globals": {"last": tid}})

        merged = self.merger.merge(results)
        if merged.conflicts:
            merged = self.merger.resolve_conflicts(
                merged, {c.description: "mantém valor do último fragmento"
                         for c in merged.conflicts})
        validated = bool(merged.text)
        return TaskResult(fragments=len(frags),
                          final_content=merged.text,
                          validated=validated,
                          conflicts=merged.conflicts)

